<?php
declare(strict_types=1);
$projectAction=(string)($_GET['action']??'');$siteId=(string)($_GET['id']??'');$canCreateSite=can($db,$user,'projects.create');$canEditSite=can($db,$user,'projects.update');if(($projectAction==='add'&&!$canCreateSite)||($projectAction==='edit'&&!$canEditSite))$projectAction='';
$siteStatsStmt=$db->prepare('SELECT p.*,(SELECT COUNT(DISTINCT m.category) FROM materials m WHERE m.project_id=p.id AND m.company_id=p.company_id) material_categories,(SELECT COUNT(*) FROM materials m WHERE m.project_id=p.id AND m.company_id=p.company_id) materials_count,(SELECT GROUP_CONCAT(DISTINCT u.name ORDER BY u.name SEPARATOR ", ") FROM user_projects up JOIN users u ON u.id=up.user_id JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE up.project_id=p.id AND r.code IN("SITE_SUPERVISOR","OWNER")) manager_names FROM projects p WHERE p.company_id=? AND (EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.company_id=p.company_id AND r.code IN("OWNER","OPERATIONS_HEAD")) OR EXISTS(SELECT 1 FROM user_projects up WHERE up.user_id=? AND up.project_id=p.id)) ORDER BY p.updated_at DESC');
$siteStatsStmt->execute([$user['company_id'],$user['id'],$user['id']]);$sites=$siteStatsStmt->fetchAll();$editingSite=null;if($projectAction==='edit'&&$siteId){foreach($sites as $candidate)if($candidate['id']===$siteId)$editingSite=$candidate;}$activeUsers=array_values(array_filter($users,fn($teamUser)=>$teamUser['status']==='active'));
?>
<section class="page-title sites-title"><div><span class="eyebrow">PROJECTS</span><h1>Construction Sites</h1><p class="muted">View the construction sites assigned to your account.</p></div><?php if($projectAction):?><a class="text-button back-sites" href="?page=projects">Back to sites</a><?php elseif($canCreateSite):?><a class="button add-site-button" href="?page=projects&action=add"><span>＋</span> Add Site</a><?php endif;?></section>
<?php if($projectAction==='add'):?>
<form class="form-card site-editor" method="post"><div class="editor-head"><div><h2>Add new construction site</h2><p class="muted">Required fields are marked with an asterisk. A unique site code will be generated automatically.</p></div></div><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><div class="auto-code-note"><strong>Site code</strong><span>Generated automatically when you create the site</span></div><div class="form-grid"><label class="field">Site name <b>*</b><input name="name" required></label><label class="field">Location <b>*</b><input name="location" required></label><label class="field">Project type <b>*</b><select name="project_type" required><option value="">Select project type</option><option value="residential">Residential</option><option value="commercial">Commercial</option><option value="mixed">Mixed</option></select></label><label class="field">Developer <b>*</b><input name="developer" required></label><label class="field">Project manager <b>*</b><select name="project_manager_id" required><option value="">Select project manager</option><?php foreach($activeUsers as $manager):?><option value="<?=e($manager['id'])?>"><?=e($manager['name'].($manager['designation']?' · '.$manager['designation']:''))?></option><?php endforeach;?></select></label><label class="field">Start date<input type="date" name="start_date"></label><label class="field">Expected completion<input type="date" name="expected_completion"></label></div><label class="field">Description<textarea name="description" rows="4"></textarea></label><div class="editor-actions"><a class="text-button" href="?page=projects">Cancel</a><button class="button" name="add_project" value="1">Create Site</button></div></form>
<?php elseif($editingSite):?><form class="form-card site-editor" method="post"><div class="editor-head"><div><span class="eyebrow">MANAGE SITE</span><h2><?=e($editingSite['name'])?></h2><p class="muted"><?=e($editingSite['location'].' · '.$editingSite['code'])?></p></div><a class="button" href="?page=construction&project=<?=e($editingSite['id'])?>">Open dashboard</a></div><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="project_id" value="<?=e($editingSite['id'])?>"><div class="form-grid"><label class="field">Construction progress %<input type="number" name="progress" min="0" max="100" value="<?=(int)$editingSite['progress']?>"></label><label class="field">Site status<select name="status"><?php foreach(['upcoming','ongoing','on_hold','completed','cancelled'] as $status):?><option value="<?=$status?>" <?=$editingSite['status']===$status?'selected':''?>><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach;?></select></label></div><button class="button" name="update_project" value="1">Save Site</button></form>
<?php else:?><section class="site-grid"><?php foreach($sites as $site):?><article class="site-card"><div class="site-card-main"><div class="site-pin">⌖</div><div class="site-identity"><div class="site-name-line"><h2><?=e($site['name'])?></h2><span class="site-status <?=e($site['status'])?>"><?=e(strtoupper(str_replace('_','-',$site['status'])))?></span></div><p><?=e($site['location'])?></p><div class="site-details"><span><small>Site code</small><?=e($site['code'])?></span><span><small>Project type</small><?=e(ucfirst($site['project_type']))?></span><span><small>Developer</small><?=e($site['developer']?:'Not added')?></span><span><small>Project manager</small><?=e($site['manager_names']?:'Not assigned')?></span></div></div></div><div class="site-metrics"><div><strong><?=(int)$site['material_categories']?></strong><small>Material categories</small></div><div><strong><?=(int)$site['materials_count']?></strong><small>Total materials</small></div></div><div class="site-card-actions"><?php if($canEditSite):?><a class="text-button" href="?page=projects&action=edit&id=<?=e($site['id'])?>">Edit</a><?php endif;?><a class="button" href="?page=construction&project=<?=e($site['id'])?>">Open Site →</a></div></article><?php endforeach;?><?php if(!$sites):?><div class="empty-site"><h2>No assigned construction sites</h2><p>Ask the administrator to assign a site to this account.</p><?php if($canCreateSite):?><a class="button" href="?page=projects&action=add">Add Site</a><?php endif;?></div><?php endif;?></section><?php endif;?>
